import{_ as a,o as e,c as s,ah as n}from"./chunks/framework.sPHStHqt.js";const p=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md","lastUpdated":1789630599000}'),o={name:"getting-started/installation.md"};function i(r,t,l,d,h,c){return e(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>This page is an operator&#39;s overview of what it takes to stand the platform up. The step-by-step commands live in the module&#39;s own technical README; here we cover what you need in place and what the process gives you, so you know what you&#39;re aiming for.</p><div class="info custom-block"><p class="custom-block-title">Audience</p><p>Setting the platform up is a <strong>technical</strong> task, usually done once by whoever hosts it. If that&#39;s not you, hand this page and the module README to your developer or host — then pick up this guide at <a href="/super-admin/dashboard">The Dashboard</a>.</p></div><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li><strong>Krayin CRM v2.2.6</strong> — the SaaS module installs on top of it.</li><li><strong>PHP 8.3 or newer</strong> and <strong>Composer 2.x</strong>.</li><li>A <strong>database</strong> and <strong>mail</strong> service, configured as for any Krayin install.</li><li>A domain you control, with <strong>wildcard DNS</strong> — because every tenant gets a subdomain (<code>*.yourplatform.com</code>), your DNS and web server must route all subdomains to the platform.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Install the SaaS module <strong>before</strong> installing Krayin itself, and don&#39;t seed the database with the usual Krayin seeder. The SaaS module has its own installer that sets the platform up correctly — running the standard Krayin install first will get in its way.</p></div><h2 id="what-installation-does" tabindex="-1">What installation does <a class="header-anchor" href="#what-installation-does" aria-label="Permalink to &quot;What installation does&quot;">​</a></h2><p>Once your developer has added the module and run its installer, the process will:</p><ol><li><strong>Set your platform&#39;s address.</strong> The app is pointed at your main domain — the address your super-admin panel lives on.</li><li><strong>Prepare the database</strong> for multi-tenancy, adding the tenant stamping that keeps each tenant&#39;s data separate (see <a href="/getting-started/architecture">Architecture</a>).</li><li><strong>Create your super-admin account.</strong> The installer asks for the email and password you&#39;ll use to sign in. If you accept the defaults, that&#39;s <code>admin@example.com</code> with a default password — <strong>change the password immediately</strong> after your first sign-in.</li></ol><h2 id="wildcard-subdomains" tabindex="-1">Wildcard subdomains <a class="header-anchor" href="#wildcard-subdomains" aria-label="Permalink to &quot;Wildcard subdomains&quot;">​</a></h2><p>Because tenants live on subdomains, the single most important hosting detail is that <strong><code>*.yourplatform.com</code> resolves to the platform</strong>. If a new tenant signs up as <code>acme</code> and <code>acme.yourplatform.com</code> doesn&#39;t load, it&#39;s almost always because wildcard DNS or the web server&#39;s wildcard host rule isn&#39;t set up. Get this working before you onboard real tenants.</p><p>For local testing, this guide&#39;s own instance uses hostnames like <code>site1.krayin-saas.com</code> mapped in the host machine&#39;s <code>hosts</code> file — the same idea as wildcard DNS, done by hand.</p><h2 id="first-sign-in" tabindex="-1">First sign-in <a class="header-anchor" href="#first-sign-in" aria-label="Permalink to &quot;First sign-in&quot;">​</a></h2><p>With the platform installed, open the super-admin panel:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://yourplatform.com/super/login</span></span></code></pre></div><p>Sign in with the account the installer created. From here, the rest of this guide takes over.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>Connect Stripe and set your logo → <a href="/settings/configuration">Configuration</a></li><li>Create your first plans → <a href="/subscriptions/plan-management">Plan Management</a></li><li>Onboard your first tenant → <a href="/tenants/registration">Registration</a> · <a href="/super-admin/tenant-management">Tenant Management</a></li></ul>',18)])])}const m=a(o,[["render",i]]);export{p as __pageData,m as default};
